234:     // Each thread executes thread_function() which has two stages:
235:     //   1) Initialise cache z-levels and starting locations
236:     //   2) Trace contours
237:     // Each stage is performed on a chunk by chunk basis.  There is a barrier between the two stages
238:     // to synchronise the threads so the cache setup is complete before being used by the trace.
239:     _next_chunk = 0;      // Next available chunk index.
240:     _finished_count = 0;  // Count of threads that have finished the cache init.
241: 
242:     // Main thread releases GIL for remainder of this function.
