261: void ThreadedContourGenerator::thread_function(std::vector<py::list>& return_lists)
262: {
263:     // Function that is executed by each of the threads.
264:     // _next_chunk starts at zero and increases up to 2*_n_chunks.  A thread in need of work reads
265:     // _next_chunk and increments it, then processes that chunk.  For _next_chunk < _n_chunks this
266:     // is stage 1 (init cache levels and starting locations) and for _next_chunk >= _n_chunks this
267:     // is stage 2 (trace contours).  There is a synchronisation barrier between the two stages so
268:     // that the cache initialisation is complete before being used by the contour trace.
269: 
270:     auto n_chunks = get_n_chunks();
271:     index_t chunk;
272:     ChunkLocal local;
273: 
274:     // Stage 1: Initialise cache z-levels and starting locations.
275:     while (true) {
276:         {
277:             std::lock_guard<std::mutex> guard(_chunk_mutex);
278:             if (_next_chunk < n_chunks)
279:                 chunk = _next_chunk++;
280:             else
281:                 break;  // No more work to do.
282:         }
283: 
284:         get_chunk_limits(chunk, local);
285:         init_cache_levels_and_starts(&local);
286:         local.clear();
287:     }
288: 
289:     {
290:         // Implementation of multithreaded barrier.  Each thread increments the shared counter.
291:         // Last thread to finish notifies the other threads that they can all continue.
292:         std::unique_lock<std::mutex> lock(_chunk_mutex);
293:         _finished_count++;
294:         if (_finished_count == _n_threads)
295:             _condition_variable.notify_all();
296:         else
297:             _condition_variable.wait(lock);
298:     }
299: 
300:     // Stage 2: Trace contours.
301:     while (true) {
302:         {
303:             std::lock_guard<std::mutex> guard(_chunk_mutex);
304:             if (_next_chunk < 2*n_chunks)
305:                 chunk = _next_chunk++ - n_chunks;
306:             else
307:                 break;  // No more work to do.
308:         }
309: 
310:         get_chunk_limits(chunk, local);
311:         march_chunk(local, return_lists);
312:         local.clear();
313:     }
314: }
